package br.edu.fatecgru;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.ImageView;
import android.widget.RadioButton;
import android.widget.RadioGroup;
import android.widget.Toast;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import java.util.ArrayList;
import java.util.List;

public class QuizActivity extends AppCompatActivity {

    RadioGroup rdgOpcoes;
    RadioButton rdbOpcao1, rdbOpcao2, rdbOpcao3, rdbOpcao4;
    ImageView imgBandeira;
    Button btnConfirma;

    int indiceAtual = 0;
    int pontos = 0;
    List<Pergunta> listaDePerguntas = new ArrayList<>();

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_quiz);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        rdbOpcao1 = findViewById(R.id.rdbOpcao1);
        rdbOpcao2 = findViewById(R.id.rdbOpcao2);
        rdbOpcao3 = findViewById(R.id.rdbOpcao3);
        rdbOpcao4 = findViewById(R.id.rdbOpcao4);
        rdgOpcoes = findViewById(R.id.rdgOpcoes);
        btnConfirma = findViewById(R.id.btnConfirma);
        imgBandeira = findViewById(R.id.imgBandeira);

        listaDePerguntas.add(new Pergunta(R.drawable.um, "Estados Unidos da América", new String[]{"Estados Unidos da América", "Argentina", "Chile", "México"}));
        listaDePerguntas.add(new Pergunta(R.drawable.dois, "Alemanha", new String[]{"Bélgica", "Peru", "Alemanha", "Puerto Rico"}));
        listaDePerguntas.add(new Pergunta(R.drawable.tres, "Itália", new String[]{"Nigéria", "França", "Brasil", "Itália"}));
        listaDePerguntas.add(new Pergunta(R.drawable.quatro, "Bósnia e Herzegovina", new String[]{"Bósnia e Herzegovina", "Bulgária", "Sérvia", "Bielorrússia"}));
        listaDePerguntas.add(new Pergunta(R.drawable.cinco, "Brasil", new String[]{"Brasil", "Noruega", "Croácia", "Alemanha"}));
        listaDePerguntas.add(new Pergunta(R.drawable.seis, "Espanha", new String[]{"Portugal", "Espanha", "Andorra", "Quênia"}));
        listaDePerguntas.add(new Pergunta(R.drawable.sete, "Escócia", new String[]{"Tonga", "Irlanda", "País de Gales", "Escócia"}));
        listaDePerguntas.add(new Pergunta(R.drawable.oito, "Taiwan", new String[]{"China", "Taiwan", "Tailãndia", "Vietnã"}));
        listaDePerguntas.add(new Pergunta(R.drawable.nove, "Uruguai", new String[]{"Uruguai", "Argentina", "Cuba", "Paraguai"}));
        listaDePerguntas.add(new Pergunta(R.drawable.dez, "Austrália", new String[]{"Austrália", "Nova Zelândia", "Inglaterra", "Ilhas Virgens Britânicas"}));
        exibirPergunta();
    }

    public class Pergunta {
        private int imgBandeira; //ID da bandeira
        private String correto; //se a resposta estiver certa
        private String[] opcoes; //Array onde vai conter as opções nos botões

        public Pergunta(int imgBandeira, String correto, String[] opcoes) {
            this.imgBandeira = imgBandeira;
            this.correto = correto;
            this.opcoes = opcoes;
        }

        public int getImgBandeira() {
            return imgBandeira;
        }

        public String getCorreto() {
            return correto;
        }

        public String[] getOpcoes() {
            return opcoes;
        }
    }

    private void exibirPergunta() {
        Pergunta p = listaDePerguntas.get(indiceAtual);

        imgBandeira.setImageResource(p.getImgBandeira());
        rdbOpcao1.setText(p.getOpcoes()[0]);
        rdbOpcao2.setText(p.getOpcoes()[1]);
        rdbOpcao3.setText(p.getOpcoes()[2]);
        rdbOpcao4.setText(p.getOpcoes()[3]);

        rdgOpcoes.clearCheck();
    }

    public void confimar(View v) {
        int selecionado = rdgOpcoes.getCheckedRadioButtonId();

        if (selecionado == -1) {
            Toast.makeText(this, "Selecione uma resposta", Toast.LENGTH_SHORT).show();
            return;
        }

        RadioButton rdbSelecionado = findViewById(selecionado); //variavel temporaria, so vai marcar qual opção foi selecionada
        String respUsuario = rdbSelecionado.getText().toString();

        Pergunta perguntaAtual = listaDePerguntas.get(indiceAtual);
        if (respUsuario.equals(perguntaAtual.getCorreto()))
            pontos++;

        //continua as perguntas até acabar
        indiceAtual++;

        if(indiceAtual < listaDePerguntas.size()){
            exibirPergunta();
        } else {
            Intent it = new Intent(QuizActivity.this, ResultadoActivity.class);
            it.putExtra("pontos", pontos);
            it.putExtra("total", listaDePerguntas.size());
            startActivity(it);
            finish();
        }
    }
}

text:
O problema do `null` está acontecendo por causa de uma característica do Android: **os dados não "viajam" automaticamente entre todas as telas**. 

Se você enviou o nome da `MainActivity` para a `QuizActivity`, ele está guardado na `QuizActivity`. Quando você abre a `ResultadoActivity`, você precisa pegar esse nome de novo e enviá-lo adiante.

Aqui estão os dois ajustes que você precisa fazer:

### 1. Na `MainActivity.java`
O comando `edtNome.getText()` retorna um objeto do tipo "Editable". O ideal para passar via Intent é transformar em texto puro (`String`).

```java
public void quiz(View v) {
    Intent it = new Intent(getApplicationContext(), QuizActivity.class);
    // Adicione o .toString() aqui:
    it.putExtra("nomeUsuario", edtNome.getText().toString()); 
    startActivity(it);
}
```

### 2. Na `QuizActivity.java` (Onde o problema realmente está)
Quando o quiz termina e você cria a Intent para a `ResultadoActivity`, você esqueceu de incluir o nome nela. A `QuizActivity` precisa ser a "ponte".

**Procure o seu método `confimar` e ajuste o final dele:**

```java
// ... dentro do else (quando acaba o quiz) ...
} else {
    Intent it = new Intent(QuizActivity.this, ResultadoActivity.class);
    it.putExtra("pontos", pontos);
    it.putExtra("total", listaDePerguntas.size());

    // ADICIONE ESTA LINHA:
    // Pegamos o nome que veio da MainActivity e colocamos na nova 'it'
    String nomeQueVeioDaMain = getIntent().getStringExtra("nomeUsuario");
    it.putExtra("nomeUsuario", nomeQueVeioDaMain);

    startActivity(it);
    finish();
}
```

### Por que isso é necessário?
Imagine que o `Intent` é um envelope. 
1. A `MainActivity` coloca o nome no envelope e manda para a `QuizActivity`.
2. A `QuizActivity` abre o envelope e lê o nome.
3. Quando a `QuizActivity` vai abrir a `ResultadoActivity`, ela cria um **novo envelope**. Se ela não colocar o nome nesse novo envelope, a `ResultadoActivity` vai receber um envelope vazio (por isso o `null`).

**Tente aplicar essas duas mudanças e o nome deve aparecer corretamente na tela final!** Se precisar de ajuda para localizar as linhas exatas, me avise.

